//! Running comparator networks on a block of vectors.
//!
//! Small stacks (n up to `Vector::UNROLL`) run a straight-line network generated by
//! `build.rs`, so every wire lives in a register. Deeper stacks sort aligned chunks with the
//! same register-resident networks and then run the remaining (rank-pruned) Batcher merge
//! levels from a comparator list over an L1-resident buffer. Stacks whose buffer outgrows L1
//! ([`DEEP_NET_BYTES`]) merge the sorted chunks with a register-blocked bitonic network instead
//! ([`NetPlan::Deep`]): each pass loads a group of 8 to 32 wires, runs several merge layers on
//! them in registers and stores them back, so the buffer (which outgrows L1 there) is read
//! once per pass rather than twice per comparator.

use crate::netgen::{self, Comparator};
use crate::simd::{Element, Vector};
use std::collections::HashMap;
use std::sync::{Arc, Mutex, OnceLock};

include!(concat!(env!("OUT_DIR"), "/unrolled.rs"));

#[derive(Debug, Clone)]
pub enum NetPlan {
    /// n <= 1: nothing to do.
    Trivial,
    /// Straight-line network; `kind` 0 = full sort, 1 = median-pruned.
    Unrolled { n: usize, kind: u8 },
    /// Unrolled sorts of aligned `chunk`-wide blocks, then interpreted merge levels.
    Hybrid { n: usize, chunk: usize, suffix: Arc<Vec<Comparator>> },
    /// Interpreted comparator list.
    Interp(Arc<Vec<Comparator>>),
    /// Sorted `chunk`-wide blocks, then register-blocked bitonic merge passes.
    Deep(Arc<Deep>),
}

/// On AVX-512, stacks whose buffer (`n` vectors) is larger than this use [`NetPlan::Deep`]:
/// the hybrid network's interpreted merge levels are fast while the buffer stays in L1 (48 KiB
/// on the Sapphire Rapids-class core measured; the crossover there was between 768 and 900
/// frames of 64-byte vectors).
pub const DEEP_NET_BYTES: usize = 48 * 1024;

/// A deep network: the flip variant of Batcher's bitonic sort (every comparator puts the
/// minimum on the lower wire, so wires past `n` hold +inf and never move), after unrolled sorts
/// of aligned `chunk`-wide blocks. Merge stage `s` (blocks of `2^s` wires) is a flip layer,
/// wire `i` against `i ^ (2^s - 1)`, then half-cleaners with strides `2^(s-2)` down to 1; its
/// layers are cut into passes of at most `log2(max group)` layers, and every pass runs on
/// groups of `2^r` wires that only meet each other in those `r` layers.
#[derive(Debug, Clone)]
pub struct Deep {
    pub n: usize,
    /// Next power of two of `n`.
    pub p2: usize,
    /// Width of the unrolled chunk sorts (1: none).
    pub chunk: usize,
    /// Chunks to sort, or all when `None` (rank pruning).
    pub chunk_live: Option<Vec<u32>>,
    pub passes: Vec<Pass>,
    /// Comparators that run (for reporting).
    pub comparators: usize,
}

/// One register-blocked pass of a [`Deep`] network.
#[derive(Debug, Clone)]
pub struct Pass {
    /// Groups have `2^r` wires and run `r` layers.
    pub r: u8,
    /// Merge stage: blocks of `2^s` wires.
    pub s: u8,
    /// Whether the pass starts with the stage's flip layer.
    pub flip: bool,
    /// Wire `u` of a group is `base + (u << sh)` (the lower half of a flip group; its upper
    /// half mirrors it, `wire(w - 1 - u) ^ (2^s - 1)`).
    pub sh: u8,
    /// Groups whose wires are all below `n` to run, or all of them when `None` (rank pruning).
    pub live: Option<Vec<u32>>,
    /// Groups that reach past `n`. Their real wires are a prefix of the group, so the layers
    /// that pair it only with padding drop out: each runs as a narrower group.
    pub partial: Vec<Partial>,
}

/// A group of a [`Pass`] that reaches past `n`: run the first `2^r` of its wires (`nr` of them
/// real) as a group of that width, starting with a flip layer if `flip`.
#[derive(Debug, Clone, Copy)]
pub struct Partial {
    pub j: u32,
    pub r: u8,
    pub flip: bool,
    pub nr: u8,
}

/// Comparators of a group of `2^r` wires, as local wire pairs: a flip layer (wire `u` against
/// `w - 1 - u`) if `flip`, then half-cleaners down to stride 1.
pub fn local_net(r: u8, flip: bool) -> Vec<(usize, usize)> {
    let w = 1usize << r;
    let mut v = Vec::new();
    let mut m = w / 2;
    if flip {
        for u in 0..w / 2 {
            v.push((u, w - 1 - u));
        }
        m = w / 4;
    }
    while m >= 1 {
        for u in 0..w {
            if u & m == 0 {
                v.push((u, u + m));
            }
        }
        m /= 2;
    }
    v
}

impl Pass {
    /// Wires of group `j`, in increasing order.
    #[inline(always)]
    pub fn wires(&self, j: usize, out: &mut [usize]) {
        let (r, sh) = (self.r as usize, self.sh as usize);
        let w = 1usize << r;
        if self.flip {
            let s = self.s as usize;
            let base = ((j >> sh) << s) | (j & ((1 << sh) - 1));
            let mask = (1usize << s) - 1;
            for u in 0..w / 2 {
                out[u] = base + (u << sh);
                out[w - 1 - u] = out[u] ^ mask;
            }
        } else {
            let base = ((j >> sh) << (sh + r)) | (j & ((1 << sh) - 1));
            for u in 0..w {
                out[u] = base + (u << sh);
            }
        }
    }
}

impl Deep {
    /// Build the network for `n` wires pruned to `needed` (all wires when `None`), with chunk
    /// sorts `chunk` wide (a power of two, or 1) and groups of at most `2^g` wires.
    pub fn new(n: usize, needed: Option<&[usize]>, chunk: usize, g: usize) -> Deep {
        assert!(chunk.is_power_of_two() && g >= 1 && n >= 2);
        let p2 = n.next_power_of_two();
        let first = chunk.trailing_zeros() as usize + 1;
        let last = p2.trailing_zeros() as usize;
        let mut passes = Vec::new();
        for s in first..=last {
            // s layers (the flip, then strides 2^(s-2) .. 1) in balanced passes of <= g
            let np = s.div_ceil(g);
            let mut top = s; // layers left: exponents top-1 .. 0, the flip counting as s-1
            for i in 0..np {
                let r = s / np + usize::from(i < s % np);
                let flip = i == 0;
                passes.push(Pass { r: r as u8, s: s as u8, flip, sh: (top - r) as u8, live: None, partial: vec![] });
                top -= r;
            }
        }
        let mut d = Deep { n, p2, chunk, chunk_live: None, passes, comparators: 0 };
        // Backwards liveness at group granularity: a group runs if any of its wires is needed
        // later; then all of its wires are needed before it.
        let mut live = vec![needed.is_none(); p2];
        if let Some(r) = needed {
            for &k in r {
                if k < n {
                    live[k] = true;
                }
            }
        }
        let mut wires = vec![0usize; 1 << g];
        for p in d.passes.iter_mut().rev() {
            let w = 1usize << p.r;
            let full_net = local_net(p.r, p.flip).len();
            let (mut keep, mut nfull) = (Vec::new(), 0);
            let mut partial = Vec::new();
            for j in 0..p2 >> p.r {
                p.wires(j, &mut wires[..w]);
                let nr = wires[..w].partition_point(|&x| x < n);
                if nr == w {
                    nfull += 1;
                    if wires[..w].iter().any(|&x| live[x]) {
                        wires[..w].iter().for_each(|&x| live[x] = true);
                        keep.push(j as u32);
                        d.comparators += full_net;
                    }
                    continue;
                }
                // Wires increase within a group, so the real ones are a prefix. A layer whose
                // pairs all reach into an all-padding upper half does nothing; drop it.
                let (mut r, mut flip) = (p.r, p.flip);
                while r > 0 && nr <= (1usize << r) / 2 {
                    r -= 1;
                    flip = false;
                }
                if r == 0 || !wires[..nr].iter().any(|&x| live[x]) {
                    continue;
                }
                wires[..nr].iter().for_each(|&x| live[x] = true);
                d.comparators += local_net(r, flip).iter().filter(|&&(_, b)| b < nr).count();
                partial.push(Partial { j: j as u32, r, flip, nr: nr as u8 });
            }
            p.live = if keep.len() == nfull { None } else { Some(keep) };
            p.partial = partial;
        }
        if chunk > 1 {
            let nc = n.div_ceil(chunk);
            let keep: Vec<u32> = (0..nc as u32)
                .filter(|&c| (c as usize * chunk..((c as usize + 1) * chunk).min(n)).any(|x| live[x]))
                .collect();
            for &c in &keep {
                let w = (n - c as usize * chunk).min(chunk);
                d.comparators += netgen::batcher(w).len();
            }
            d.chunk_live = if keep.len() == nc { None } else { Some(keep) };
        }
        d
    }

    /// The same network as a comparator list (tests).
    #[cfg(test)]
    pub fn comparator_list(&self) -> Vec<Comparator> {
        let mut out = Vec::new();
        if self.chunk > 1 {
            let chunks: Vec<usize> = match &self.chunk_live {
                None => (0..self.n.div_ceil(self.chunk)).collect(),
                Some(l) => l.iter().map(|&c| c as usize).collect(),
            };
            for c in chunks {
                let s = c * self.chunk;
                let w = (self.n - s).min(self.chunk);
                out.extend(netgen::batcher(w).iter().map(|&(a, b)| (a + s as u16, b + s as u16)));
            }
        }
        let mut wires = vec![0usize; 64];
        for p in &self.passes {
            let w = 1usize << p.r;
            let net = local_net(p.r, p.flip);
            let groups: Vec<usize> = match &p.live {
                None => (0..self.p2 >> p.r)
                    .filter(|&j| {
                        p.wires(j, &mut wires[..w]);
                        wires[w - 1] < self.n
                    })
                    .collect(),
                Some(l) => l.iter().map(|&j| j as usize).collect(),
            };
            for j in groups {
                p.wires(j, &mut wires[..w]);
                for &(a, b) in &net {
                    out.push((wires[a] as u16, wires[b] as u16));
                }
            }
            for q in &p.partial {
                p.wires(q.j as usize, &mut wires[..w]);
                for (a, b) in local_net(q.r, q.flip) {
                    if b < q.nr as usize {
                        out.push((wires[a] as u16, wires[b] as u16));
                    }
                }
            }
        }
        out
    }
}

impl NetPlan {
    /// Comparators this plan executes (for reporting).
    pub fn comparators(&self) -> usize {
        match self {
            NetPlan::Trivial => 0,
            NetPlan::Unrolled { n, kind } => {
                let full = netgen::batcher(*n);
                if *kind == 0 {
                    full.len()
                } else {
                    netgen::prune(&full, *n, &netgen::median_ranks(*n)).len()
                }
            }
            NetPlan::Hybrid { n, chunk, suffix } => {
                let mut c = 0;
                let mut s = 0;
                while s < *n {
                    let w = (*n - s).min(*chunk);
                    c += netgen::batcher(w).len();
                    s += w;
                }
                c + suffix.len()
            }
            NetPlan::Interp(v) => v.len(),
            NetPlan::Deep(d) => d.comparators,
        }
    }
}

type Key = (usize, Vec<usize>);
fn cache() -> &'static Mutex<HashMap<Key, Arc<(Vec<Comparator>, Vec<u32>)>>> {
    static C: OnceLock<Mutex<HashMap<Key, Arc<(Vec<Comparator>, Vec<u32>)>>>> = OnceLock::new();
    C.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Batcher network for `n` wires pruned to `needed` (all wires when `None`), with levels.
fn pruned_with_levels(n: usize, needed: Option<&[usize]>) -> Arc<(Vec<Comparator>, Vec<u32>)> {
    let mut key_r: Vec<usize> = needed.map(|r| r.to_vec()).unwrap_or_default();
    key_r.sort_unstable();
    key_r.dedup();
    let key = (n, if needed.is_some() { key_r.clone() } else { vec![usize::MAX] });
    if let Some(v) = cache().lock().unwrap().get(&key) {
        return v.clone();
    }
    let (full, lv) = netgen::batcher_levels(n);
    let v = match needed {
        None => (full, lv),
        Some(_) => {
            // prune while keeping the level tags aligned
            let mut live = vec![false; n];
            for &k in &key_r {
                if k < n {
                    live[k] = true;
                }
            }
            let mut keep = Vec::new();
            for (i, &(a, b)) in full.iter().enumerate().rev() {
                if live[a as usize] || live[b as usize] {
                    live[a as usize] = true;
                    live[b as usize] = true;
                    keep.push(i);
                }
            }
            keep.reverse();
            (keep.iter().map(|&i| full[i]).collect(), keep.iter().map(|&i| lv[i]).collect())
        }
    };
    let v = Arc::new(v);
    let mut c = cache().lock().unwrap();
    if c.len() > 256 {
        c.clear();
    }
    c.insert(key, v.clone());
    v
}

type DeepKey = (usize, Vec<usize>, usize, usize);
fn deep_cache() -> &'static Mutex<HashMap<DeepKey, Arc<Deep>>> {
    static C: OnceLock<Mutex<HashMap<DeepKey, Arc<Deep>>>> = OnceLock::new();
    C.get_or_init(|| Mutex::new(HashMap::new()))
}

/// The deep network for `n` wires and this ISA's register budget, cached.
pub fn deep_plan(n: usize, needed: Option<&[usize]>, unroll: usize) -> Arc<Deep> {
    // Chunks: the widest unrolled sort. Groups: half the vector registers (32 on AVX-512 and
    // NEON, 16 on AVX2) hold a group plus temporaries; the portable fallback keeps 4.
    let mut chunk = 1;
    while chunk * 2 <= unroll.min(MAX_UNROLL) {
        chunk *= 2;
    }
    let g = match unroll {
        0 => 2,
        u if u >= 24 => deep_group_log2(),
        _ => 3,
    };
    let mut r: Vec<usize> = needed.map(|r| r.to_vec()).unwrap_or_else(|| vec![usize::MAX]);
    r.sort_unstable();
    r.dedup();
    let key = (n, r, chunk, g);
    if let Some(d) = deep_cache().lock().unwrap().get(&key) {
        return d.clone();
    }
    let d = Arc::new(Deep::new(n, needed, chunk, g));
    let mut c = deep_cache().lock().unwrap();
    if c.len() > 64 {
        c.clear();
    }
    c.insert(key, d.clone());
    d
}

/// log2 of the widest group on 32-register ISAs (`RANKWISE_DEEP_GROUP` overrides it, 1..=5,
/// for measuring other CPUs).
fn deep_group_log2() -> usize {
    static G: OnceLock<usize> = OnceLock::new();
    *G.get_or_init(|| {
        std::env::var("RANKWISE_DEEP_GROUP")
            .ok()
            .and_then(|s| s.parse().ok())
            .filter(|g| (1..=5).contains(g))
            .unwrap_or(4)
    })
}

/// Pick the fastest way to deliver ranks `needed` (`None` = a full sort) of `n` wires of
/// `vec_bytes`-byte vectors, given that stacks up to `unroll` wires fit the unrolled networks.
pub fn plan(n: usize, needed: Option<&[usize]>, unroll: usize, vec_bytes: usize) -> NetPlan {
    if n <= 1 {
        return NetPlan::Trivial;
    }
    // Measured on AVX-512 only (32 registers: groups of 16). On AVX2, groups of 8 lost to
    // the hybrid at every depth tried (up to 2,400 frames), and NEON is unmeasured, so both
    // keep the hybrid.
    let deep = match deep_threshold() {
        Some(t) => n > t,
        None => unroll >= 32 && n > MAX_UNROLL && n * vec_bytes > DEEP_NET_BYTES,
    };
    if deep {
        return NetPlan::Deep(deep_plan(n, needed, unroll));
    }
    let is_median = needed.map(|r| {
        let mut r = r.to_vec();
        r.sort_unstable();
        r.dedup();
        r == netgen::median_ranks(n)
    });
    let pr = pruned_with_levels(n, needed);
    if n <= unroll.min(MAX_UNROLL) {
        let kind = if is_median == Some(true) { 1 } else { 0 };
        if kind == 0 && needed.is_some() {
            // A tiny rank set (say, the minimum) can be far cheaper interpreted.
            let full = netgen::batcher(n).len();
            if pr.0.len() * 3 < full {
                return NetPlan::Interp(Arc::new(pr.0.clone()));
            }
        }
        return NetPlan::Unrolled { n, kind };
    }
    let mut chunk = 1;
    while chunk * 2 <= unroll.min(MAX_UNROLL) {
        chunk *= 2;
    }
    if chunk >= 8 {
        let suffix: Vec<Comparator> =
            pr.0.iter().zip(pr.1.iter()).filter(|(_, &l)| l as usize >= chunk).map(|(&c, _)| c).collect();
        return NetPlan::Hybrid { n, chunk, suffix: Arc::new(suffix) };
    }
    NetPlan::Interp(Arc::new(pr.0.clone()))
}

/// `RANKWISE_DEEP_NET`: stacks deeper than this many frames use the deep network, whatever
/// the vector width (for measuring other CPUs; default: [`DEEP_NET_BYTES`]).
fn deep_threshold() -> Option<usize> {
    static T: OnceLock<Option<usize>> = OnceLock::new();
    *T.get_or_init(|| std::env::var("RANKWISE_DEEP_NET").ok().and_then(|s| s.parse().ok()))
}

/// Interpreted bitonic merger for `n` wires (valley-shaped input).
pub fn bitonic_plan(n: usize) -> NetPlan {
    if n <= 1 {
        NetPlan::Trivial
    } else {
        NetPlan::Interp(Arc::new(netgen::bitonic_merge(n)))
    }
}

#[inline(always)]
unsafe fn interp<V: Vector>(b: *mut V, net: &[Comparator]) {
    for &(i, j) in net {
        let x = *b.add(i as usize);
        let y = *b.add(j as usize);
        *b.add(i as usize) = x.min(y);
        *b.add(j as usize) = x.max(y);
    }
}

#[inline(always)]
unsafe fn cx<V: Vector>(x: &mut [V], a: usize, b: usize) {
    let (p, q) = (x[a], x[b]);
    x[a] = p.min(q);
    x[b] = p.max(q);
}

/// The layers of one group, in registers (`W` and `FLIP` are constants, so the loops unroll).
#[inline(always)]
unsafe fn local<V: Vector, const W: usize, const FLIP: bool>(x: &mut [V; W]) {
    let mut m = W / 2;
    if FLIP {
        for u in 0..W / 2 {
            cx(x, u, W - 1 - u);
        }
        m = W / 4;
    }
    while m >= 1 {
        for u in 0..W {
            if u & m == 0 {
                cx(x, u, u + m);
            }
        }
        m /= 2;
    }
}

#[inline(always)]
unsafe fn pass_w<V: Vector, const W: usize, const FLIP: bool>(b: *mut V, n: usize, p2: usize, p: &Pass) {
    let mut wires = [0usize; W];
    let mut x = [V::splat(V::E::MAX); W];
    // A macro, not a closure: closures inside #[target_feature] functions may not inline.
    macro_rules! group {
        ($j:expr) => {{
            p.wires($j, &mut wires);
            for u in 0..W {
                x[u] = *b.add(wires[u]);
            }
            local::<V, W, FLIP>(&mut x);
            for u in 0..W {
                *b.add(wires[u]) = x[u];
            }
        }};
    }
    match &p.live {
        None => {
            for j in 0..p2 / W {
                // groups reaching past n are in `partial`
                p.wires(j, &mut wires);
                if wires[W - 1] < n {
                    group!(j);
                }
            }
        }
        Some(l) => {
            for &j in l {
                group!(j as usize);
            }
        }
    }
}

/// A group reaching past `n`: its first `W` wires, `nr` of them real (the rest +inf).
#[inline(always)]
unsafe fn partial_w<V: Vector, const W: usize, const FLIP: bool>(b: *mut V, wires: &[usize], nr: usize) {
    // Loops over the constant W (with a predictable test), not up to nr: indexing the group
    // with a runtime bound would keep it on the stack instead of in registers.
    let mut x = [V::splat(V::E::MAX); W];
    for u in 0..W {
        if u < nr {
            x[u] = *b.add(wires[u]);
        }
    }
    local::<V, W, FLIP>(&mut x);
    for u in 0..W {
        if u < nr {
            *b.add(wires[u]) = x[u];
        }
    }
}

#[inline(always)]
unsafe fn partials<V: Vector>(b: *mut V, p: &Pass) {
    let mut wires = [0usize; 32];
    let w = 1usize << p.r;
    for q in &p.partial {
        p.wires(q.j as usize, &mut wires[..w]);
        let nr = q.nr as usize;
        match (q.r, q.flip) {
            (1, _) => partial_w::<V, 2, false>(b, &wires, nr),
            (2, false) => partial_w::<V, 4, false>(b, &wires, nr),
            (2, true) => partial_w::<V, 4, true>(b, &wires, nr),
            (3, false) => partial_w::<V, 8, false>(b, &wires, nr),
            (3, true) => partial_w::<V, 8, true>(b, &wires, nr),
            (4, false) => partial_w::<V, 16, false>(b, &wires, nr),
            (4, true) => partial_w::<V, 16, true>(b, &wires, nr),
            (5, false) => partial_w::<V, 32, false>(b, &wires, nr),
            (5, true) => partial_w::<V, 32, true>(b, &wires, nr),
            _ => unreachable!(),
        }
    }
}

#[inline(always)]
unsafe fn deep<V: Vector>(b: *mut V, d: &Deep) {
    if d.chunk > 1 && V::UNROLL > 0 {
        match &d.chunk_live {
            None => {
                let mut s = 0;
                while s < d.n {
                    unrolled::<V>(b.add(s), (d.n - s).min(d.chunk), 0);
                    s += d.chunk;
                }
            }
            Some(l) => {
                for &c in l {
                    let s = c as usize * d.chunk;
                    unrolled::<V>(b.add(s), (d.n - s).min(d.chunk), 0);
                }
            }
        }
    }
    for p in &d.passes {
        match (p.r, p.flip) {
            (1, _) => pass_w::<V, 2, false>(b, d.n, d.p2, p),
            (2, false) => pass_w::<V, 4, false>(b, d.n, d.p2, p),
            (2, true) => pass_w::<V, 4, true>(b, d.n, d.p2, p),
            (3, false) => pass_w::<V, 8, false>(b, d.n, d.p2, p),
            (3, true) => pass_w::<V, 8, true>(b, d.n, d.p2, p),
            (4, false) => pass_w::<V, 16, false>(b, d.n, d.p2, p),
            (4, true) => pass_w::<V, 16, true>(b, d.n, d.p2, p),
            (5, false) => pass_w::<V, 32, false>(b, d.n, d.p2, p),
            (5, true) => pass_w::<V, 32, true>(b, d.n, d.p2, p),
            _ => unreachable!(),
        }
        partials::<V>(b, p);
    }
}

/// Run `plan` on the `n` vectors at `b`.
#[inline(always)]
pub unsafe fn apply<V: Vector>(b: *mut V, plan: &NetPlan) {
    match plan {
        NetPlan::Trivial => {}
        NetPlan::Unrolled { n, kind } => {
            if V::UNROLL > 0 {
                unrolled::<V>(b, *n, *kind)
            }
        }
        NetPlan::Hybrid { n, chunk, suffix } => {
            if V::UNROLL > 0 {
                let mut s = 0;
                while s < *n {
                    let w = (*n - s).min(*chunk);
                    unrolled::<V>(b.add(s), w, 0);
                    s += w;
                }
            }
            interp(b, suffix);
        }
        NetPlan::Interp(net) => interp(b, net),
        NetPlan::Deep(d) => deep(b, d),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// 0-1 principle: a comparator network sorts every input iff it sorts every 0-1 input.
    fn sorts_01(n: usize, net: &[Comparator], needed: Option<&[usize]>) -> bool {
        for bits in 0u32..(1u32 << n) {
            let mut v: Vec<u8> = (0..n).map(|i| ((bits >> i) & 1) as u8).collect();
            for &(a, b) in net {
                let (a, b) = (a as usize, b as usize);
                if v[a] > v[b] {
                    v.swap(a, b);
                }
            }
            let mut want: Vec<u8> = (0..n).map(|i| ((bits >> i) & 1) as u8).collect();
            want.sort_unstable();
            let ok = match needed {
                None => v == want,
                Some(r) => r.iter().all(|&k| v[k] == want[k]),
            };
            if !ok {
                return false;
            }
        }
        true
    }

    #[test]
    fn deep_networks_sort_every_01_input() {
        for n in 2..=16 {
            for chunk in [1usize, 2, 4, 8] {
                for g in 1..=4 {
                    let d = Deep::new(n, None, chunk, g);
                    assert!(sorts_01(n, &d.comparator_list(), None), "n={n} chunk={chunk} g={g}");
                    let med = netgen::median_ranks(n);
                    let pr = Deep::new(n, Some(&med), chunk, g);
                    assert!(pr.comparators <= d.comparators);
                    assert!(sorts_01(n, &pr.comparator_list(), Some(&med)), "median n={n} chunk={chunk} g={g}");
                    let few = [0, n - 1];
                    let pf = Deep::new(n, Some(&few), chunk, g);
                    assert!(sorts_01(n, &pf.comparator_list(), Some(&few)), "ends n={n} chunk={chunk} g={g}");
                }
            }
        }
    }

    #[test]
    fn deep_execution_matches_its_comparator_list() {
        use crate::simd::scalar::F32s;
        let mut seed = 7u64;
        for n in [2usize, 3, 5, 17, 33, 100, 257, 600, 1025] {
            for chunk in [1usize, 16] {
                for g in [1usize, 3, 4, 5] {
                    for needed in [None, Some(netgen::median_ranks(n)), Some(vec![n / 7, n - 1])] {
                        let d = Deep::new(n, needed.as_deref(), chunk, g);
                        let vals: Vec<[f32; 8]> = (0..n)
                            .map(|_| {
                                core::array::from_fn(|_| {
                                    seed ^= seed << 13;
                                    seed ^= seed >> 7;
                                    seed ^= seed << 17;
                                    (seed % 97) as f32
                                })
                            })
                            .collect();
                        let mut buf: Vec<F32s> = vals.iter().map(|v| unsafe { F32s::load(v.as_ptr()) }).collect();
                        // the portable vector type has no unrolled networks: sort chunks here
                        if chunk > 1 {
                            let mut want = vals.clone();
                            for s in (0..n).step_by(chunk) {
                                let e = (s + chunk).min(n);
                                for lane in 0..8 {
                                    let mut c: Vec<f32> = want[s..e].iter().map(|v| v[lane]).collect();
                                    c.sort_by(|a, b| a.partial_cmp(b).unwrap());
                                    for (k, x) in c.into_iter().enumerate() {
                                        want[s + k][lane] = x;
                                    }
                                }
                            }
                            buf = want.iter().map(|v| unsafe { F32s::load(v.as_ptr()) }).collect();
                        }
                        unsafe { deep::<F32s>(buf.as_mut_ptr(), &d) };
                        for lane in 0..8 {
                            let mut c: Vec<f32> = vals.iter().map(|v| v[lane]).collect();
                            c.sort_by(|a, b| a.partial_cmp(b).unwrap());
                            let got: Vec<f32> = buf
                                .iter()
                                .map(|v| {
                                    let mut a = [0f32; 8];
                                    unsafe { v.store(a.as_mut_ptr()) };
                                    a[lane]
                                })
                                .collect();
                            match &needed {
                                None => assert_eq!(got, c, "n={n} chunk={chunk} g={g}"),
                                Some(r) => {
                                    for &k in r {
                                        assert_eq!(got[k], c[k], "n={n} chunk={chunk} g={g} rank {k}");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
